import { ref, computed, watch, onUnmounted } from 'vue'
import { supabase } from '@/lib/supabase'
import { useBranch } from './useBranch'
import { useI18nStore } from '@/stores/i18n'
import type { RealtimeChannel } from '@supabase/supabase-js'

export interface InventoryItemWithAlerts {
  ingredient_id: string
  sku: string
  name_vi: string
  name_en: string
  name_ja: string
  unit: string
  unit_cost: number
  category_id: string
  category_name_vi: string
  quantity: number
  low_stock_threshold: number
  is_low_stock: boolean
  next_expiry_date: string | null
}

function daysUntil(dateStr: string) {
  const d1 = new Date()
  d1.setHours(0, 0, 0, 0)
  const d2 = new Date(dateStr)
  d2.setHours(0, 0, 0, 0)
  return Math.floor((d2.getTime() - d1.getTime()) / (1000 * 60 * 60 * 24))
}

export function useInventory() {
  const { activeBranchId } = useBranch()
  const i18n = useI18nStore()

  const inventory = ref<InventoryItemWithAlerts[]>([])
  const loading = ref(false)
  const error = ref<string | null>(null)

  let subscription: RealtimeChannel | null = null

  const lowStockItems = computed(() => {
    return inventory.value.filter(i => i.is_low_stock)
  })

  const expiringItems = computed(() => {
    return inventory.value.filter(i => i.next_expiry_date && daysUntil(i.next_expiry_date) <= 3)
  })

  function handleError(err: any): string {
    const msg = err?.message || String(err)
    if (msg.includes('INSUFFICIENT_STOCK')) {
      return i18n.t('errors.insufficient_stock') || 'Not enough stock'
    }
    return msg
  }

  async function fetchInventory() {
    if (!activeBranchId.value) return
    loading.value = true
    error.value = null
    try {
      const { data, error: err } = await supabase
        .rpc('get_inventory_with_alerts', { p_branch_id: activeBranchId.value })

      if (err) throw err
      inventory.value = (data as InventoryItemWithAlerts[]) || []
    } catch (err: any) {
      error.value = handleError(err)
      throw err
    } finally {
      loading.value = false
    }
  }

  async function addStock(
    ingredientId: string, 
    quantity: number, 
    type: 'IN' | 'OUT' | 'ADJUST' | 'WASTE' | 'TRANSFER_IN' | 'TRANSFER_OUT', 
    note?: string, 
    expiryDate?: string
  ) {
    if (!activeBranchId.value) throw new Error('No active branch')
    error.value = null
    try {
      const { data, error: err } = await supabase
        .rpc('create_inventory_transaction', {
          p_branch_id: activeBranchId.value,
          p_ingredient_id: ingredientId,
          p_type: type,
          p_quantity: quantity,
          p_note: note || null,
          p_expiry_date: expiryDate || null,
          p_reference_type: null,
          p_reference_id: null,
          p_unit_cost: null,
          p_created_by: undefined
        })

      if (err) throw err
      return data
    } catch (err: any) {
      error.value = handleError(err)
      throw err
    }
  }

  async function adjustStock(ingredientId: string, newQty: number) {
    const item = inventory.value.find(i => i.ingredient_id === ingredientId)
    if (!item) throw new Error('Item not found in current inventory')

    const delta = newQty - item.quantity
    if (delta === 0) return

    return addStock(ingredientId, delta, 'ADJUST', 'Stock adjustment')
  }

  function subscribeToStockUpdates() {
    if (!activeBranchId.value) return
    if (subscription) {
      supabase.removeChannel(subscription)
    }
    subscription = supabase.channel(`inventory_stock_${activeBranchId.value}`)
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'inventory_stock', filter: `branch_id=eq.${activeBranchId.value}` },
        () => {
          fetchInventory()
        }
      )
      .subscribe()
  }

  function unsubscribe() {
    if (subscription) {
      supabase.removeChannel(subscription)
      subscription = null
    }
  }

  // Refetch and resubscribe when branch changes
  watch(activeBranchId, (newBranch) => {
    if (newBranch) {
      fetchInventory()
      subscribeToStockUpdates()
    } else {
      inventory.value = []
      unsubscribe()
    }
  }, { immediate: true })

  onUnmounted(() => {
    unsubscribe()
  })

  // To preserve backwards-compatibility from the previous useInventory version
  async function listLowStock() {
    if (inventory.value.length === 0) {
      await fetchInventory()
    }
    return lowStockItems.value
  }

  return {
    inventory,
    loading,
    error,
    lowStockItems,
    expiringItems,
    fetchInventory,
    addStock,
    adjustStock,
    subscribeToStockUpdates,
    unsubscribe,
    listLowStock
  }
}

import { ref } from 'vue'
import { supabase } from '@/lib/supabase'

export function usePurchasing() {
  const loading = ref(false)
  const error = ref<string | null>(null)

  const suppliers = ref<any[]>([])
  const ingredients = ref<any[]>([])
  const currentStock = ref<any[]>([])

  // 1. Submit Goods Receipt (RPC) - use submit_goods_receipt
  const submitGoodsReceipt = async (
    branchId: string,
    receiptCode: string,
    supplierId: string,
    scanImageUrl: string,
    items: Array<any>
  ) => {
    loading.value = true
    error.value = null

    try {
      const { data, error: submitError } = await supabase.rpc('submit_goods_receipt', {
        p_branch_id: branchId,
        p_receipt_code: receiptCode,
        p_supplier_id: supplierId,
        p_purchase_order_id: null,
        p_scan_image_url: scanImageUrl,
        p_items: items
      })

      if (submitError) throw submitError

      return true
    } catch (err: any) {
      console.error('Error submitting goods receipt:', err)
      error.value = err.message || 'Lỗi khi nhập hàng'
      throw err
    } finally {
      loading.value = false
    }
  }

  // 2. Lấy danh sách Nhà cung cấp (RPC)
  const fetchSuppliers = async () => {
    try {
      const { data, error: fetchError } = await supabase.rpc('get_suppliers')
      if (fetchError) throw fetchError
      suppliers.value = data || []
      return data
    } catch (err: any) {
      console.error('Error fetching suppliers:', err)
      return []
    }
  }

  // 3. Lấy danh sách Nguyên vật liệu (RPC)
  const fetchIngredients = async () => {
    try {
      const { data, error: fetchError } = await supabase.rpc('get_ingredients')
      if (fetchError) throw fetchError
      ingredients.value = data || []
      return data
    } catch (err: any) {
      console.error('Error fetching ingredients:', err)
      return []
    }
  }

  // 4. Lấy tồn kho hiện tại (RPC)
  const fetchCurrentStock = async (branchId?: string) => {
    try {
      const { data, error: fetchError } = await supabase.rpc('get_current_stock', {
        p_branch_id: branchId || undefined
      })
      if (fetchError) throw fetchError
      currentStock.value = data || []
      return data
    } catch (err: any) {
      console.error('Error fetching current stock:', err)
      return []
    }
  }

  // 5. Nộp phiếu kiểm kho (Audit)
  const submitAudit = async (
    items: Array<{ item_id: string; new_quantity: number; notes: string }>
  ) => {
    loading.value = true
    error.value = null
    try {
      const promises = items.map(item => {
        return supabase.rpc('record_inventory_transaction', {
          p_ingredient_id: item.item_id,
          p_transaction_type: 'ADJUST',
          p_quantity: item.new_quantity,
          p_unit_cost: 0,
          p_supplier_id: null,
          p_notes: 'Kiểm kho: ' + item.notes
        })
      })

      const results = await Promise.all(promises)
      for (const result of results) {
        if (result.error) throw result.error
      }
      return true
    } catch (err: any) {
      console.error('Error submitting audit:', err)
      error.value = err.message || 'Lỗi khi lưu kiểm kho'
      throw err
    } finally {
      loading.value = false
    }
  }

  // 6. Upload ảnh scan phiếu giao hàng (Lên Supabase Storage)
  const uploadScanImage = async (file: File) => {
    try {
      const fileExt = file.name.split('.').pop()
      const fileName = `${Math.random()}.${fileExt}`
      const filePath = `receipts/${fileName}`

      const { error: uploadError, data } = await supabase.storage
        .from('purchasing')
        .upload(filePath, file)

      if (uploadError) throw uploadError

      const { data: { publicUrl } } = supabase.storage
        .from('purchasing')
        .getPublicUrl(filePath)

      return publicUrl
    } catch (err: any) {
      console.error('Error uploading scan image:', err)
      throw err
    }
  }

  const fetchPurchaseOrders = async () => [];
  return {
    fetchPurchaseOrders,
    loading,
    error,
    suppliers,
    ingredients,
    currentStock,
    submitGoodsReceipt,
    fetchSuppliers,
    fetchIngredients,
    fetchCurrentStock,
    submitAudit,
    uploadScanImage
  }
}

import { ref, computed } from 'vue'
import { supabase } from '@/lib/supabase'
import { useBranch } from './useBranch'
import { useAuth } from './useAuth'

export type RequisitionType = 'OUTBOUND' | 'INBOUND' | 'RETURN'
export type RequisitionStatus = 'PENDING' | 'APPROVED' | 'REJECTED' | 'PROCESSING' | 'COMPLETED' | 'CANCELLED'

export interface RequisitionItem {
  id: string
  requisition_id: string
  ingredient_id: string
  requested_quantity: number
  approved_quantity: number | null
  actual_quantity: number | null
  unit: string
  note: string | null
  ingredients?: {
    id: string
    name_vi: string
    name_en: string | null
    name_ja: string | null
    sku: string
  }
}

export interface Requisition {
  id: string
  branch_id: string
  requisition_number: string
  type: RequisitionType
  status: RequisitionStatus
  requested_by: string
  approved_by: string | null
  approved_at: string | null
  rejection_reason: string | null
  needed_by_date: string | null
  note: string | null
  created_at: string
  updated_at: string
  requested_by_profile?: { id: string, raw_user_meta_data: any }
  approved_by_profile?: { id: string, raw_user_meta_data: any }
  requisition_items?: RequisitionItem[]
}

export function useRequisition() {
  const { activeBranchId } = useBranch()
  const { profile } = useAuth()

  const requisitions = ref<Requisition[]>([])
  const loading = ref(false)
  const error = ref<string | null>(null)

  const pendingCount = computed(() => {
    return requisitions.value.filter(r => r.status === 'PENDING').length
  })

  async function fetchRequisitions(filters?: { status?: RequisitionStatus, type?: RequisitionType }) {
    if (!activeBranchId.value) return

    loading.value = true
    error.value = null

    try {
      let query = supabase
        .from('requisitions')
        .select(`
          *,
          requested_by_profile:requested_by (
            id, raw_user_meta_data
          ),
          approved_by_profile:approved_by (
            id, raw_user_meta_data
          ),
          requisition_items (
            id, requested_quantity, approved_quantity, actual_quantity, unit, note, ingredient_id,
            ingredients (id, name_vi, name_en, name_ja, sku)
          )
        `)
        .eq('branch_id', activeBranchId.value)
        .order('created_at', { ascending: false })

      if (filters?.status) {
        query = query.eq('status', filters.status)
      }
      if (filters?.type) {
        query = query.eq('type', filters.type)
      }

      const { data, error: err } = await query

      if (err) throw err

      requisitions.value = data as unknown as Requisition[]
    } catch (e: any) {
      error.value = e.message
      throw e
    } finally {
      loading.value = false
    }
  }

  async function createRequisition(
    type: RequisitionType,
    items: Array<{ ingredient_id: string; requested_quantity: number; unit: string; note?: string }>,
    neededByDate?: string,
    note?: string
  ) {
    if (!activeBranchId.value) throw new Error('No active branch')
    if (!profile.value?.id) throw new Error('Not authenticated')

    loading.value = true
    error.value = null

    try {
      const { data, error: err } = await supabase.rpc('create_requisition_with_items', {
        p_branch_id: activeBranchId.value,
        p_type: type,
        p_requested_by: profile.value.id,
        p_items: items,
        p_needed_by_date: neededByDate || null,
        p_note: note || null
      })

      if (err) throw err
      await fetchRequisitions()
      return data
    } catch (e: any) {
      error.value = e.message
      throw e
    } finally {
      loading.value = false
    }
  }

  async function approveRequisition(
    id: string,
    approvedQtys?: Array<{ requisition_item_id: string; approved_quantity: number }>
  ) {
    if (!profile.value?.id) throw new Error('Not authenticated')

    loading.value = true
    error.value = null

    try {
      const { error: err } = await supabase.rpc('approve_reject_requisition', {
        p_requisition_id: id,
        p_action: 'APPROVE',
        p_performed_by: profile.value.id,
        p_note: null,
        p_approved_qtys: approvedQtys || null
      })

      if (err) throw err
      await fetchRequisitions()
    } catch (e: any) {
      error.value = e.message
      throw e
    } finally {
      loading.value = false
    }
  }

  async function rejectRequisition(id: string, reason: string) {
    if (!profile.value?.id) throw new Error('Not authenticated')

    loading.value = true
    error.value = null

    try {
      const { error: err } = await supabase.rpc('approve_reject_requisition', {
        p_requisition_id: id,
        p_action: 'REJECT',
        p_performed_by: profile.value.id,
        p_note: reason,
        p_approved_qtys: null
      })

      if (err) throw err
      await fetchRequisitions()
    } catch (e: any) {
      error.value = e.message
      throw e
    } finally {
      loading.value = false
    }
  }

  async function confirmDelivery(
    id: string,
    actualQtys: Array<{ requisition_item_id: string; actual_quantity: number; expiry_date?: string }>
  ) {
    if (!profile.value?.id) throw new Error('Not authenticated')

    loading.value = true
    error.value = null

    try {
      const { error: err } = await supabase.rpc('complete_requisition_delivery', {
        p_requisition_id: id,
        p_completed_by: profile.value.id,
        p_actual_qtys: actualQtys
      })

      if (err) throw err
      await fetchRequisitions()
    } catch (e: any) {
      error.value = e.message
      throw e
    } finally {
      loading.value = false
    }
  }

  return {
    requisitions,
    loading,
    error,
    pendingCount,
    fetchRequisitions,
    createRequisition,
    approveRequisition,
    rejectRequisition,
    confirmDelivery
  }
}

import { ref } from 'vue'
import { supabase } from '@/lib/supabase'

export function useAccounting() {
  const taxReports = ref<any[]>([])
  const taxRecords = ref<any[]>([])
  const loading = ref(false)
  const error = ref<string | null>(null)

  // 1. Fetch Tax Report using RPC
  const fetchTaxReport = async (startDate: string, endDate: string) => {
    loading.value = true
    error.value = null

    try {
      const { data, error: supaError } = await supabase.rpc('get_tax_report', {
        p_start_date: startDate,
        p_end_date: endDate
      })

      if (supaError) throw supaError

      taxReports.value = data || []
      return data
    } catch (err: any) {
      console.error('Error fetching tax report:', err)
      error.value = err.message
      return null
    } finally {
      loading.value = false
    }
  }

  const fetchTaxRecords = async () => {
    loading.value = true
    error.value = null

    try {
      const { data, error: supaError } = await supabase.rpc('get_tax_records')

      if (supaError) throw supaError

      taxRecords.value = data || []
      return data
    } catch (err: any) {
      console.error('Error fetching tax records:', err)
      error.value = err.message
      return null
    } finally {
      loading.value = false
    }
  }

  const generateTaxRecord = async (periodType: string, startDate: string, endDate: string) => {
    loading.value = true
    error.value = null

    try {
      // Need branch_id, assuming current branch from user profile, but wait: 
      // the RPC generate_tax_record takes p_branch_id. If we don't have it, we might need to get it from useAuth.
      // For now, pass a dummy or let the RPC handle it if we fetch it.
      // Wait, let's just fetch from session or let it throw if branch_id is required. 
      // Let's pass the branch_id from the user session.
      const { data: userData } = await supabase.auth.getUser()
      const branchId = userData.user?.user_metadata?.branch_id || '00000000-0000-0000-0000-000000000000'

      const { data, error: supaError } = await supabase.rpc('generate_tax_record', {
        p_branch_id: branchId,
        p_period_type: periodType,
        p_period_start: startDate,
        p_period_end: endDate
      })

      if (supaError) throw supaError

      return data
    } catch (err: any) {
      console.error('Error generating tax record:', err)
      error.value = err.message
      throw err
    } finally {
      loading.value = false
    }
  }

  const finalizeTaxRecord = async (recordId: string) => {
    loading.value = true
    error.value = null

    try {
      const { error: supaError } = await supabase.rpc('finalize_tax_record', {
        p_record_id: recordId
      })

      if (supaError) throw supaError

      return true
    } catch (err: any) {
      console.error('Error finalizing tax record:', err)
      error.value = err.message
      throw err
    } finally {
      loading.value = false
    }
  }

  // 2. Thay the hoa don (Replace Invoice) using the RPC to prevent Race Condition
  const replaceInvoice = async (
    billId: string, 
    newSymbol: string, 
    newNumber: string, 
    newTaxCode: string, 
    newCompany: string
  ) => {
    loading.value = true
    error.value = null

    try {
      const { data, error: rpcError } = await supabase.rpc('replace_invoice', {
        p_bill_id: billId,
        p_new_invoice_symbol: newSymbol,
        p_new_invoice_number: newNumber,
        p_buyer_tax_code: newTaxCode,
        p_buyer_company: newCompany
      })

      if (rpcError) throw rpcError
      return data // Returns the ID of the newly generated invoice
    } catch (err: any) {
      console.error('Error replacing invoice:', err)
      error.value = err.message
      throw err
    } finally {
      loading.value = false
    }
  }

  // 3. Huy hoa don khẩn cấp (Void Invoice)
  const voidInvoice = async (billId: string) => {
    loading.value = true
    error.value = null

    try {
      const { error: rpcError } = await supabase.rpc('void_invoice', {
        p_bill_id: billId
      })

      if (rpcError) throw rpcError
      return true
    } catch (err: any) {
      console.error('Error voiding invoice:', err)
      error.value = err.message
      throw err
    } finally {
      loading.value = false
    }
  }

  const getProfitLoss = async (startDate: string, endDate: string) => {
    loading.value = true
    error.value = null
    try {
      const { data, error: supaError } = await supabase.rpc('get_executive_dashboard', {
        p_period_start: startDate,
        p_period_end: endDate
      })

      if (supaError) throw supaError

      // data.totals contains total_revenue, total_expense, gross_profit
      return {
        revenue: data?.totals?.total_revenue || 0,
        expense: data?.totals?.total_expense || 0,
        profit: data?.totals?.gross_profit || 0
      }
    } catch (err: any) {
      console.error('Error getting profit loss:', err)
      error.value = err.message
      return { revenue: 0, expense: 0, profit: 0 }
    } finally {
      loading.value = false
    }
  }

  // Alias for compatibility
  const fetchProfitLoss = getProfitLoss

  return {
    taxReports,
    taxRecords,
    loading,
    error,
    fetchTaxReport,
    fetchTaxRecords,
    generateTaxRecord,
    finalizeTaxRecord,
    replaceInvoice,
    voidInvoice,
    getProfitLoss,
    fetchProfitLoss
  }
}

/**
 * useAccountingModule.ts
 * Composable for the full Accounting Module.
 * All data access goes through Supabase RPC (no direct table queries).
 */
import { ref, computed } from 'vue'
import { supabase } from '@/lib/supabase'

// ──────────────── Types ────────────────────────────────────
export interface AccountingCategory {
  id: string
  name: string
  name_en: string | null
  name_ja: string | null
  type: 'income' | 'expense'
  code: string | null
  is_system: boolean
  is_active: boolean
  created_at: string
}

export interface CashFlowEntry {
  id: string
  branch_id: string
  branch_name: string
  category_id: string | null
  category_name: string | null
  category_code: string | null
  type: 'income' | 'expense'
  amount: number
  description: string
  reference_no: string | null
  payment_method: 'cash' | 'bank_transfer' | 'card'
  status: 'draft' | 'pending' | 'approved' | 'rejected'
  entry_date: string
  approved_by: string | null
  approved_at: string | null
  reject_reason: string | null
  created_by: string | null
  creator_name: string | null
  created_at: string
  notes: string | null
  total_count?: number
}

export interface APRecord {
  id: string
  branch_id: string
  branch_name: string
  supplier_id: string | null
  supplier_name: string | null
  invoice_ref: string | null
  total_amount: number
  paid_amount: number
  outstanding: number
  due_date: string | null
  payment_date: string | null
  status: 'unpaid' | 'partial' | 'paid' | 'overdue'
  is_overdue: boolean
  notes: string | null
  created_at: string
}

export interface AccountingDashboard {
  period: { year: number; month: number }
  total_income: number
  total_expense: number
  net_cashflow: number
  pending_count: number
  draft_count: number
  ap_unpaid_count: number
  ap_unpaid_amount: number
  ap_overdue_count: number
}

export interface PLReportRow {
  category_code: string
  category_name: string
  type: 'income' | 'expense'
  month_amount: number
  ytd_amount: number
}

export interface CreateCashFlowInput {
  branch_id: string
  category_id: string | null
  type: 'income' | 'expense'
  amount: number
  description: string
  payment_method: 'cash' | 'bank_transfer' | 'card'
  entry_date: string
  reference_no?: string
  notes?: string
}

export interface CreateAPInput {
  branch_id: string
  supplier_id: string | null
  invoice_ref: string
  total_amount: number
  paid_amount: number
  due_date?: string
  notes?: string
}

// ──────────────── Composable ───────────────────────────────
export function useAccountingModule() {
  const loading = ref(false)
  const error = ref<string | null>(null)

  // State
  const dashboard = ref<AccountingDashboard | null>(null)
  const cashFlowEntries = ref<CashFlowEntry[]>([])
  const categories = ref<AccountingCategory[]>([])
  const apRecords = ref<APRecord[]>([])
  const plReport = ref<PLReportRow[]>([])
  const totalEntries = ref(0)

  // Computed
  const incomeCategories = computed(() => categories.value.filter(c => c.type === 'income'))
  const expenseCategories = computed(() => categories.value.filter(c => c.type === 'expense'))

  const plIncome = computed(() => plReport.value.filter(r => r.type === 'income'))
  const plExpense = computed(() => plReport.value.filter(r => r.type === 'expense'))
  const plNetMonth = computed(() =>
    plIncome.value.reduce((s, r) => s + Number(r.month_amount), 0) -
