export function usePurchasing() {
  const loading = ref(false)
  const error = ref<string | null>(null)

  const suppliers = ref<any[]>([])
  const ingredients = ref<any[]>([])
  const currentStock = ref<any[]>([])

  // 1. Submit Goods Receipt (RPC) - use submit_goods_receipt
  const submitGoodsReceipt = async (
    branchId: string,
    receiptCode: string,
    supplierId: string,
    scanImageUrl: string,
    items: Array<any>
  ) => {
    loading.value = true
    error.value = null

    try {
      const { data, error: submitError } = await supabase.rpc('submit_goods_receipt', {
        p_branch_id: branchId,
        p_receipt_code: receiptCode,
        p_supplier_id: supplierId,
        p_purchase_order_id: null,
        p_scan_image_url: scanImageUrl,
        p_items: items
      })

      if (submitError) throw submitError

      return true
    } catch (err: any) {
      console.error('Error submitting goods receipt:', err)
      error.value = err.message || 'Lỗi khi nhập hàng'
      throw err
    } finally {
      loading.value = false
    }
  }

  // 2. Lấy danh sách Nhà cung cấp (RPC)
  const fetchSuppliers = async () => {
    try {
      const { data, error: fetchError } = await supabase.rpc('get_suppliers')
      if (fetchError) throw fetchError
      suppliers.value = data || []
      return data
    } catch (err: any) {
      console.error('Error fetching suppliers:', err)
      return []
    }
  }

  // 3. Lấy danh sách Nguyên vật liệu (RPC)
  const fetchIngredients = async () => {
    try {
      const { data, error: fetchError } = await supabase.rpc('get_ingredients')
      if (fetchError) throw fetchError
      ingredients.value = data || []
      return data
    } catch (err: any) {
      console.error('Error fetching ingredients:', err)
      return []
    }
  }

  // 4. Lấy tồn kho hiện tại (RPC)
  const fetchCurrentStock = async (branchId?: string) => {
    try {
      const { data, error: fetchError } = await supabase.rpc('get_current_stock', {
        p_branch_id: branchId || undefined
      })
      if (fetchError) throw fetchError
      currentStock.value = data || []
      return data
    } catch (err: any) {
      console.error('Error fetching current stock:', err)
      return []
    }
  }

  // 5. Nộp phiếu kiểm kho (Audit)
  const submitAudit = async (
    items: Array<{ item_id: string; new_quantity: number; notes: string }>
  ) => {
    loading.value = true
    error.value = null
    try {
      const promises = items.map(item => {
        return supabase.rpc('record_inventory_transaction', {
          p_ingredient_id: item.item_id,
          p_transaction_type: 'ADJUST',
          p_quantity: item.new_quantity,
          p_unit_cost: 0,
          p_supplier_id: null,
          p_notes: 'Kiểm kho: ' + item.notes
        })
      })

      const results = await Promise.all(promises)
      for (const result of results) {
        if (result.error) throw result.error
      }
      return true
    } catch (err: any) {
      console.error('Error submitting audit:', err)
      error.value = err.message || 'Lỗi khi lưu kiểm kho'
      throw err
    } finally {
      loading.value = false
    }
  }

  // 6. Upload ảnh scan phiếu giao hàng (Lên Supabase Storage)
  const uploadScanImage = async (file: File) => {
    try {
      const fileExt = file.name.split('.').pop()
      const fileName = `${Math.random()}.${fileExt}`
      const filePath = `receipts/${fileName}`

      const { error: uploadError, data } = await supabase.storage
        .from('purchasing')
        .upload(filePath, file)

      if (uploadError) throw uploadError

      const { data: { publicUrl } } = supabase.storage
        .from('purchasing')
        .getPublicUrl(filePath)

      return publicUrl
    } catch (err: any) {
      console.error('Error uploading scan image:', err)
      throw err
    }
  }

  const fetchPurchaseOrders = async () => [];
  return {
    fetchPurchaseOrders,
    loading,
    error,
    suppliers,
    ingredients,
    currentStock,
    submitGoodsReceipt,
    fetchSuppliers,
    fetchIngredients,
    fetchCurrentStock,
    submitAudit,
    uploadScanImage
  }
}

import { ref, computed } from 'vue'
import { supabase } from '@/lib/supabase'
import { useBranch } from './useBranch'
import { useAuth } from './useAuth'

export type RequisitionType = 'OUTBOUND' | 'INBOUND' | 'RETURN'
export type RequisitionStatus = 'PENDING' | 'APPROVED' | 'REJECTED' | 'PROCESSING' | 'COMPLETED' | 'CANCELLED'

export interface RequisitionItem {
  id: string
  requisition_id: string
  ingredient_id: string
  requested_quantity: number
  approved_quantity: number | null
  actual_quantity: number | null
  unit: string
  note: string | null
  ingredients?: {
    id: string
    name_vi: string
    name_en: string | null
    name_ja: string | null
    sku: string
  }
}

export interface Requisition {
  id: string
  branch_id: string
  requisition_number: string
  type: RequisitionType
  status: RequisitionStatus
  requested_by: string
  approved_by: string | null
  approved_at: string | null
  rejection_reason: string | null
  needed_by_date: string | null
  note: string | null
  created_at: string
  updated_at: string
  requested_by_profile?: { id: string, raw_user_meta_data: any }
  approved_by_profile?: { id: string, raw_user_meta_data: any }
  requisition_items?: RequisitionItem[]
}

export function useRequisition() {
  const { activeBranchId } = useBranch()
  const { profile } = useAuth()

  const requisitions = ref<Requisition[]>([])
  const loading = ref(false)
  const error = ref<string | null>(null)

  const pendingCount = computed(() => {
    return requisitions.value.filter(r => r.status === 'PENDING').length
  })

  async function fetchRequisitions(filters?: { status?: RequisitionStatus, type?: RequisitionType }) {
    if (!activeBranchId.value) return

    loading.value = true
    error.value = null

    try {
      let query = supabase
        .from('requisitions')
        .select(`
          *,
          requested_by_profile:requested_by (
            id, raw_user_meta_data
          ),
          approved_by_profile:approved_by (
            id, raw_user_meta_data
          ),
          requisition_items (
            id, requested_quantity, approved_quantity, actual_quantity, unit, note, ingredient_id,
            ingredients (id, name_vi, name_en, name_ja, sku)
          )
        `)
        .eq('branch_id', activeBranchId.value)
        .order('created_at', { ascending: false })

      if (filters?.status) {
        query = query.eq('status', filters.status)
      }
      if (filters?.type) {
        query = query.eq('type', filters.type)
      }

      const { data, error: err } = await query

      if (err) throw err

      requisitions.value = data as unknown as Requisition[]
    } catch (e: any) {
      error.value = e.message
      throw e
    } finally {
      loading.value = false
    }
  }

  async function createRequisition(
    type: RequisitionType,
    items: Array<{ ingredient_id: string; requested_quantity: number; unit: string; note?: string }>,
    neededByDate?: string,
    note?: string
  ) {
    if (!activeBranchId.value) throw new Error('No active branch')
    if (!profile.value?.id) throw new Error('Not authenticated')

    loading.value = true
    error.value = null

    try {
      const { data, error: err } = await supabase.rpc('create_requisition_with_items', {
        p_branch_id: activeBranchId.value,
        p_type: type,
        p_requested_by: profile.value.id,
        p_items: items,
        p_needed_by_date: neededByDate || null,
        p_note: note || null
      })

      if (err) throw err
      await fetchRequisitions()
      return data
    } catch (e: any) {
      error.value = e.message
      throw e
    } finally {
      loading.value = false
    }
  }

  async function approveRequisition(
    id: string,
    approvedQtys?: Array<{ requisition_item_id: string; approved_quantity: number }>
  ) {
    if (!profile.value?.id) throw new Error('Not authenticated')

    loading.value = true
    error.value = null

    try {
      const { error: err } = await supabase.rpc('approve_reject_requisition', {
        p_requisition_id: id,
        p_action: 'APPROVE',
        p_performed_by: profile.value.id,
        p_note: null,
        p_approved_qtys: approvedQtys || null
      })

      if (err) throw err
      await fetchRequisitions()
    } catch (e: any) {
      error.value = e.message
      throw e
    } finally {
      loading.value = false
    }
  }

  async function rejectRequisition(id: string, reason: string) {
    if (!profile.value?.id) throw new Error('Not authenticated')

    loading.value = true
    error.value = null

    try {
      const { error: err } = await supabase.rpc('approve_reject_requisition', {
        p_requisition_id: id,
        p_action: 'REJECT',
        p_performed_by: profile.value.id,
        p_note: reason,
        p_approved_qtys: null
      })

      if (err) throw err
      await fetchRequisitions()
    } catch (e: any) {
      error.value = e.message
      throw e
    } finally {
      loading.value = false
    }
  }

  async function confirmDelivery(
    id: string,
    actualQtys: Array<{ requisition_item_id: string; actual_quantity: number; expiry_date?: string }>
  ) {
    if (!profile.value?.id) throw new Error('Not authenticated')

    loading.value = true
    error.value = null

    try {
      const { error: err } = await supabase.rpc('complete_requisition_delivery', {
        p_requisition_id: id,
        p_completed_by: profile.value.id,
        p_actual_qtys: actualQtys
      })

      if (err) throw err
      await fetchRequisitions()
    } catch (e: any) {
      error.value = e.message
      throw e
    } finally {
      loading.value = false
    }
  }

  return {
    requisitions,
    loading,
    error,
    pendingCount,
    fetchRequisitions,
    createRequisition,
    approveRequisition,
    rejectRequisition,
    confirmDelivery
  }
}

import { ref } from 'vue'
import { supabase } from '@/lib/supabase'

export function useAccounting() {
  const taxReports = ref<any[]>([])
  const taxRecords = ref<any[]>([])
  const loading = ref(false)
  const error = ref<string | null>(null)

  // 1. Fetch Tax Report using RPC
  const fetchTaxReport = async (startDate: string, endDate: string) => {
    loading.value = true
    error.value = null

    try {
      const { data, error: supaError } = await supabase.rpc('get_tax_report', {
        p_start_date: startDate,
        p_end_date: endDate
      })

      if (supaError) throw supaError

      taxReports.value = data || []
      return data
    } catch (err: any) {
      console.error('Error fetching tax report:', err)
      error.value = err.message
      return null
    } finally {
      loading.value = false
    }
  }

  const fetchTaxRecords = async () => {
    loading.value = true
    error.value = null

    try {
      const { data, error: supaError } = await supabase.rpc('get_tax_records')

      if (supaError) throw supaError

      taxRecords.value = data || []
      return data
    } catch (err: any) {
      console.error('Error fetching tax records:', err)
      error.value = err.message
      return null
    } finally {
      loading.value = false
    }
  }

  const generateTaxRecord = async (periodType: string, startDate: string, endDate: string) => {
    loading.value = true
    error.value = null

    try {
      // Need branch_id, assuming current branch from user profile, but wait: 
      // the RPC generate_tax_record takes p_branch_id. If we don't have it, we might need to get it from useAuth.
      // For now, pass a dummy or let the RPC handle it if we fetch it.
      // Wait, let's just fetch from session or let it throw if branch_id is required. 
      // Let's pass the branch_id from the user session.
      const { data: userData } = await supabase.auth.getUser()
      const branchId = userData.user?.user_metadata?.branch_id || '00000000-0000-0000-0000-000000000000'

      const { data, error: supaError } = await supabase.rpc('generate_tax_record', {
        p_branch_id: branchId,
        p_period_type: periodType,
        p_period_start: startDate,
        p_period_end: endDate
      })

      if (supaError) throw supaError

      return data
    } catch (err: any) {
      console.error('Error generating tax record:', err)
      error.value = err.message
      throw err
    } finally {
      loading.value = false
    }
  }

  const finalizeTaxRecord = async (recordId: string) => {
    loading.value = true
    error.value = null

    try {
      const { error: supaError } = await supabase.rpc('finalize_tax_record', {
        p_record_id: recordId
      })

      if (supaError) throw supaError

      return true
    } catch (err: any) {
      console.error('Error finalizing tax record:', err)
      error.value = err.message
      throw err
    } finally {
      loading.value = false
    }
  }

  // 2. Thay the hoa don (Replace Invoice) using the RPC to prevent Race Condition
  const replaceInvoice = async (
    billId: string, 
    newSymbol: string, 
    newNumber: string, 
    newTaxCode: string, 
    newCompany: string
  ) => {
    loading.value = true
    error.value = null

    try {
      const { data, error: rpcError } = await supabase.rpc('replace_invoice', {
        p_bill_id: billId,
        p_new_invoice_symbol: newSymbol,
        p_new_invoice_number: newNumber,
        p_buyer_tax_code: newTaxCode,
        p_buyer_company: newCompany
      })

      if (rpcError) throw rpcError
      return data // Returns the ID of the newly generated invoice
    } catch (err: any) {
      console.error('Error replacing invoice:', err)
      error.value = err.message
      throw err
    } finally {
      loading.value = false
    }
  }

  // 3. Huy hoa don khẩn cấp (Void Invoice)
  const voidInvoice = async (billId: string) => {
    loading.value = true
    error.value = null

    try {
      const { error: rpcError } = await supabase.rpc('void_invoice', {
        p_bill_id: billId
      })

      if (rpcError) throw rpcError
      return true
    } catch (err: any) {
      console.error('Error voiding invoice:', err)
      error.value = err.message
      throw err
    } finally {
      loading.value = false
    }
  }

  const getProfitLoss = async (startDate: string, endDate: string) => {
    loading.value = true
    error.value = null
    try {
      const { data, error: supaError } = await supabase.rpc('get_executive_dashboard', {
        p_period_start: startDate,
        p_period_end: endDate
      })

      if (supaError) throw supaError

      // data.totals contains total_revenue, total_expense, gross_profit
      return {
        revenue: data?.totals?.total_revenue || 0,
        expense: data?.totals?.total_expense || 0,
        profit: data?.totals?.gross_profit || 0
      }
    } catch (err: any) {
      console.error('Error getting profit loss:', err)
      error.value = err.message
      return { revenue: 0, expense: 0, profit: 0 }
    } finally {
      loading.value = false
    }
  }

  // Alias for compatibility
  const fetchProfitLoss = getProfitLoss

  return {
    taxReports,
    taxRecords,
    loading,
    error,
    fetchTaxReport,
    fetchTaxRecords,
    generateTaxRecord,
    finalizeTaxRecord,
    replaceInvoice,
    voidInvoice,
    getProfitLoss,
    fetchProfitLoss
  }
}

/**
 * useAccountingModule.ts
 * Composable for the full Accounting Module.
 * All data access goes through Supabase RPC (no direct table queries).
 */
import { ref, computed } from 'vue'
import { supabase } from '@/lib/supabase'

// ──────────────── Types ────────────────────────────────────
export interface AccountingCategory {
  id: string
  name: string
  name_en: string | null
  name_ja: string | null
  type: 'income' | 'expense'
  code: string | null
  is_system: boolean
  is_active: boolean
  created_at: string
}

export interface CashFlowEntry {
  id: string
  branch_id: string
  branch_name: string
  category_id: string | null
  category_name: string | null
  category_code: string | null
  type: 'income' | 'expense'
  amount: number
  description: string
  reference_no: string | null
  payment_method: 'cash' | 'bank_transfer' | 'card'
  status: 'draft' | 'pending' | 'approved' | 'rejected'
  entry_date: string
  approved_by: string | null
  approved_at: string | null
  reject_reason: string | null
  created_by: string | null
  creator_name: string | null
  created_at: string
  notes: string | null
  total_count?: number
}

export interface APRecord {
  id: string
  branch_id: string
  branch_name: string
  supplier_id: string | null
  supplier_name: string | null
  invoice_ref: string | null
  total_amount: number
  paid_amount: number
  outstanding: number
  due_date: string | null
  payment_date: string | null
  status: 'unpaid' | 'partial' | 'paid' | 'overdue'
  is_overdue: boolean
  notes: string | null
  created_at: string
}

export interface AccountingDashboard {
  period: { year: number; month: number }
  total_income: number
  total_expense: number
  net_cashflow: number
  pending_count: number
  draft_count: number
  ap_unpaid_count: number
  ap_unpaid_amount: number
  ap_overdue_count: number
}

export interface PLReportRow {
  category_code: string
  category_name: string
  type: 'income' | 'expense'
  month_amount: number
  ytd_amount: number
}

export interface CreateCashFlowInput {
  branch_id: string
  category_id: string | null
  type: 'income' | 'expense'
  amount: number
  description: string
  payment_method: 'cash' | 'bank_transfer' | 'card'
  entry_date: string
  reference_no?: string
  notes?: string
}

export interface CreateAPInput {
  branch_id: string
  supplier_id: string | null
  invoice_ref: string
  total_amount: number
  paid_amount: number
  due_date?: string
  notes?: string
}

// ──────────────── Composable ───────────────────────────────
export function useAccountingModule() {
  const loading = ref(false)
  const error = ref<string | null>(null)

  // State
  const dashboard = ref<AccountingDashboard | null>(null)
  const cashFlowEntries = ref<CashFlowEntry[]>([])
  const categories = ref<AccountingCategory[]>([])
  const apRecords = ref<APRecord[]>([])
  const plReport = ref<PLReportRow[]>([])
  const totalEntries = ref(0)

  // Computed
  const incomeCategories = computed(() => categories.value.filter(c => c.type === 'income'))
  const expenseCategories = computed(() => categories.value.filter(c => c.type === 'expense'))

  const plIncome = computed(() => plReport.value.filter(r => r.type === 'income'))
  const plExpense = computed(() => plReport.value.filter(r => r.type === 'expense'))
  const plNetMonth = computed(() =>
    plIncome.value.reduce((s, r) => s + Number(r.month_amount), 0) -
    plExpense.value.reduce((s, r) => s + Number(r.month_amount), 0)
  )
  const plNetYTD = computed(() =>
    plIncome.value.reduce((s, r) => s + Number(r.ytd_amount), 0) -
    plExpense.value.reduce((s, r) => s + Number(r.ytd_amount), 0)
  )

  async function fetchDashboard(branchId?: string | null, year?: number, month?: number) {
    loading.value = true
    error.value = null
    try {
      const { data, error: err } = await supabase.rpc('get_accounting_dashboard', {
        p_branch_id: branchId ?? null,
        p_year: year ?? null,
        p_month: month ?? null,
      })
      if (err) throw err
      dashboard.value = data as AccountingDashboard
    } catch (e: any) {
      error.value = e.message
    } finally {
      loading.value = false
    }
  }

  async function fetchCashFlowEntries(params: {
    branchId?: string | null
    start?: string | null
    end?: string | null
    type?: 'income' | 'expense' | null
    status?: string | null
    limit?: number
    offset?: number
  } = {}) {
    loading.value = true
    error.value = null
    try {
      const { data, error: err } = await supabase.rpc('get_cash_flow_entries', {
        p_branch_id: params.branchId ?? null,
        p_start: params.start ?? null,
        p_end: params.end ?? null,
        p_type: params.type ?? null,
        p_status: params.status ?? null,
        p_limit: params.limit ?? 50,
        p_offset: params.offset ?? 0,
      })
      if (err) throw err
      const rows = (data ?? []) as CashFlowEntry[]
      cashFlowEntries.value = rows
      totalEntries.value = rows.length > 0 ? Number(rows[0].total_count ?? 0) : 0
    } catch (e: any) {
      error.value = e.message
    } finally {
      loading.value = false
    }
  }

  async function createEntry(input: CreateCashFlowInput) {
    const { data, error: err } = await supabase.rpc('create_cash_flow_entry', {
      p_branch_id: input.branch_id,
      p_category_id: input.category_id,
      p_type: input.type,
      p_amount: input.amount,
      p_description: input.description,
      p_payment_method: input.payment_method,
      p_entry_date: input.entry_date,
      p_reference_no: input.reference_no ?? null,
      p_notes: input.notes ?? null,
    })
    if (err) throw err
    return data
  }

  async function updateEntry(id: string, payload: Partial<CreateCashFlowInput>) {
    const { data, error: err } = await supabase.rpc('update_cash_flow_entry', {
      p_id: id,
      p_category_id: payload.category_id ?? null,
      p_amount: payload.amount ?? null,
      p_description: payload.description ?? null,
      p_payment_method: payload.payment_method ?? null,
      p_entry_date: payload.entry_date ?? null,
      p_reference_no: payload.reference_no ?? null,
      p_notes: payload.notes ?? null,
    })
    if (err) throw err
    return data
  }

  async function submitEntry(id: string) {
    const { data, error: err } = await supabase.rpc('submit_cash_flow_entry', { p_id: id })
    if (err) throw err
    return data
  }

  async function approveEntry(id: string, action: 'approve' | 'reject', reason?: string) {
    const { data, error: err } = await supabase.rpc('approve_cash_flow_entry', {
      p_id: id,
      p_action: action,
      p_reason: reason ?? null,
    })
    if (err) throw err
    return data
  }

  async function deleteEntry(id: string) {
    const { error: err } = await supabase.rpc('delete_cash_flow_entry', { p_id: id })
    if (err) throw err
  }

  async function fetchCategories(type?: 'income' | 'expense') {
    const { data, error: err } = await supabase.rpc('get_accounting_categories', {
      p_type: type ?? null,
    })
    if (err) throw err
    categories.value = (data ?? []) as AccountingCategory[]
  }

  async function fetchAPSummary(branchId?: string | null, status?: string) {
    loading.value = true
    error.value = null
    try {
      const { data, error: err } = await supabase.rpc('get_ap_summary', {
        p_branch_id: branchId ?? null,
        p_status: status ?? null,
      })
      if (err) throw err
      apRecords.value = (data ?? []) as APRecord[]
    } catch (e: any) {
      error.value = e.message
    } finally {
      loading.value = false
    }
  }

  async function recordAPPayment(input: CreateAPInput) {
    const { data, error: err } = await supabase.rpc('record_ap_payment', {
      p_branch_id: input.branch_id,
      p_supplier_id: input.supplier_id,
      p_invoice_ref: input.invoice_ref,
      p_total_amount: input.total_amount,
      p_paid_amount: input.paid_amount,
      p_due_date: input.due_date ?? null,
      p_notes: input.notes ?? null,
    })
    if (err) throw err
    return data
  }

  async function fetchPLReport(branchId?: string | null, year?: number, month?: number) {
    loading.value = true
    error.value = null
    try {
      const { data, error: err } = await supabase.rpc('get_pl_report', {
        p_branch_id: branchId ?? null,
        p_year: year ?? null,
        p_month: month ?? null,
      })
      if (err) throw err
      plReport.value = (data ?? []) as PLReportRow[]
    } catch (e: any) {
      error.value = e.message
    } finally {
      loading.value = false
    }
  }

  return {
    // State
    loading, error,
    dashboard, cashFlowEntries, categories,
    apRecords, plReport, totalEntries,
    // Computed
    incomeCategories, expenseCategories,
    plIncome, plExpense, plNetMonth, plNetYTD,
    // Actions
    fetchDashboard,
    fetchCashFlowEntries,
    createEntry, updateEntry, submitEntry, approveEntry, deleteEntry,
    fetchCategories,
    fetchAPSummary, recordAPPayment,
    fetchPLReport,
  }
}

import { ref } from 'vue'
import { supabase } from '@/lib/supabase'
import { callEdgeFunction } from '@/utils/edge'

// NOTE: payload keys MUST match the Edge Function contract (camelCase):
// `supabase/functions/close-shift/index.ts` takes `{ shiftId, closingCash, notes }`
// `supabase/functions/open-shift/index.ts` takes `{ branchId, openingCash, notes }`
// `supabase/functions/export-shift-csv/index.ts` reads `?shiftId=<uuid>` from the
// URL (returns raw CSV text, not JSON).
export interface OpenShiftPayload {
  branchId: string
  openingCash: number
  notes?: Record<string, unknown>
}

export interface ShiftOpenResponse {
  ok: boolean
  idempotent?: boolean
  shift: {
    id: string
    branch_id: string
    user_id: string
    status: 'open' | 'closed'
    opened_at: string
    opening_cash: string | number
  }
}

export interface CloseShiftPayload {
  shiftId: string
  closingCash: number
  notes?: string
}

export interface CloseShiftResponse {
  ok?: boolean
  shift?: { id: string; closed_at: string }
  summary?: Record<string, { count: number; total: number }>
  expectedCash?: number
  closingCash?: number
  cashDifference?: number
  error?: string
}

export interface ExportShiftCsvResponse {
  csv: string
  rowCount: number
}

export function useShift() {
  const loading = ref(false)
  const error = ref<string | null>(null)

  async function openShift(payload: OpenShiftPayload): Promise<ShiftOpenResponse> {
    loading.value = true
    error.value = null
    try {
      // 1. Try Edge Function first
      return await callEdgeFunction<OpenShiftPayload, ShiftOpenResponse>(
        'open-shift',
        payload,
      )
    } catch (edgeErr) {
      console.warn('[useShift] Edge Function open-shift failed, trying direct RPC:', edgeErr)
      // 2. Fallback: call shift_open RPC directly via Supabase client
      try {
        const { data, error: rpcErr } = await supabase.rpc('shift_open', {
          p_branch_id: payload.branchId,
          p_opening_cash: payload.openingCash,
          p_notes: payload.notes ?? {},
        })
        if (rpcErr) throw rpcErr
        if (!data) throw new Error('shift_open RPC returned no data')
        return data as ShiftOpenResponse
      } catch (rpcErr) {
        error.value = rpcErr instanceof Error ? rpcErr.message : String(rpcErr)
        throw rpcErr
      }
    } finally {
      loading.value = false
    }
  }

  async function closeShift(
    payload: CloseShiftPayload,
  ): Promise<CloseShiftResponse> {
    loading.value = true
    error.value = null
    try {
      const res = await callEdgeFunction<CloseShiftPayload, CloseShiftResponse>(
        'close-shift',
        payload,
      )
      // Edge Function may return 200 with { ok: false } for business errors
      // (e.g. unsettled orders)
      if (res && res.ok === false && res.error) {
        throw new Error(res.error)
      }
      return res
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e)
      // Provide a more helpful message for common failures
      if (msg.includes('Failed to fetch') || msg.includes('fetch')) {
        error.value = 'Không thể kết nối đến server. Vui lòng kiểm tra kết nối mạng và thử lại.'
      } else if (msg.includes('unsettled_orders') || msg.includes('chưa thanh toán')) {
        error.value = msg
      } else {
        error.value = msg
      }
      throw e
    } finally {
      loading.value = false
    }
  }

  async function exportCsv(shiftId: string): Promise<string> {
    const { data: sessionData } = await supabase.auth.getSession()
    const token = sessionData.session?.access_token
    const supabaseUrl = import.meta.env.VITE_SUPABASE_URL
    if (!token || !supabaseUrl) {
      throw new Error('Không có session — vui lòng đăng nhập lại.')
    }
    loading.value = true
    error.value = null
    try {
      const url = `${supabaseUrl}/functions/v1/export-shift-csv?shiftId=${encodeURIComponent(shiftId)}`
      const res = await fetch(url, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${token}`,
          apikey: import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY ?? '',
        },
      })
      if (!res.ok) {
        const text = await res.text().catch(() => '')
        throw new Error(text || `Export CSV thất bại (HTTP ${res.status})`)
      }
      return await res.text()
    } catch (e) {
      error.value = e instanceof Error ? e.message : String(e)
      throw e
    } finally {
      loading.value = false
    }
  }

  return { loading, error, openShift, closeShift, exportCsv }
}

